import TodaysWeather from "./components/TodaysWeather/TodaysWeather";
import WeeklyWeather from "./components/WeeklyWeather/WeeklyWeather";

import "./App.css";
import { useState } from "react";

function App() {
  const [input, setInput] = useState("");

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          setInput(e.target[0].value);
          e.target.reset();
        }}
      >
        <input type="text" value="yerevan" placeholder=""/>
        <input type="submit" />
      </form>
      <TodaysWeather city={input} />
      <WeeklyWeather city={input} />
    </div>
  );
}

export default App;
